package com.italiano2774.nativeapp;
import android.os.Bundle;import android.speech.tts.TextToSpeech;import android.text.*;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.appcompat.app.AlertDialog;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import java.util.*;
public class EmergencyFragment extends Fragment implements TextToSpeech.OnInitListener{
 private EmergencyRepository repo;private EmergencyPhraseAdapter adapter;private Spinner category;private EditText search;private TextView count;private TextToSpeech tts;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_emergency,c,false);repo=EmergencyRepository.get(requireContext());tts=new TextToSpeech(requireContext(),this);category=v.findViewById(R.id.spinner_emergency_category);search=v.findViewById(R.id.edit_emergency_search);count=v.findViewById(R.id.text_emergency_count);List<String> names=new ArrayList<>();names.add("全部场景");for(EmergencyCategory e:repo.categories())names.add(e.category);ArrayAdapter<String> sa=new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_item,names);sa.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);category.setAdapter(sa);category.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){filter();}});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){filter();}public void afterTextChanged(Editable e){}});RecyclerView rv=v.findViewById(R.id.recycler_emergency);rv.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new EmergencyPhraseAdapter(new EmergencyPhraseAdapter.Actions(){public void speak(EmergencyPhrase p){say(p.it);}public void save(EmergencyPhrase p){CustomLibraryRepository.add(requireContext(),"sentence",p.it,p.zh,"救急 · "+p.category,id->Toast.makeText(requireContext(),"已加入个人句子库",Toast.LENGTH_SHORT).show());}public void show(EmergencyPhrase p){TextView t=new TextView(requireContext());t.setPadding(40,30,40,30);t.setText(p.it+"\n\n"+p.zh);t.setTextSize(24);new AlertDialog.Builder(requireContext()).setTitle(p.category).setView(t).setNegativeButton("关闭",null).setPositiveButton("🔊 播放",(d,w)->say(p.it)).show();}});rv.setAdapter(adapter);filter();return v;}
 private void filter(){if(adapter==null)return;String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);String cat=category.getSelectedItem()==null?"全部场景":category.getSelectedItem().toString();List<EmergencyPhrase> out=new ArrayList<>();for(EmergencyPhrase p:repo.all()){if(!cat.equals("全部场景")&&!p.category.equals(cat))continue;if(!q.isEmpty()&&!(p.it+" "+p.zh).toLowerCase(Locale.ROOT).contains(q))continue;out.add(p);}adapter.submit(out);count.setText("显示 "+out.size()+" / "+repo.all().size()+" 句");}
 private void say(String s){if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"emergency");}public void onInit(int status){if(status==TextToSpeech.SUCCESS){tts.setLanguage(Locale.ITALY);tts.setSpeechRate(0.88f);}}@Override public void onDestroyView(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroyView();}
}
